$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$adb=& adb devices 2>$null;if($LASTEXITCODE -or !($adb|Select-String "\tdevice$")){throw 'A connected, authorized Android emulator/device is required for the M9 instrumentation evaluation.'}
$out=Join-Path $PSScriptRoot 'results/reliability-results.csv';Write-Warning "This run overwrites $out";Push-Location $root
try{$log=& ./gradlew connectedDebugAndroidTest --info '-Pandroid.testInstrumentationRunnerArguments.class=com.example.crowdtransportfeedback.data.repository.M9ReliabilityEvaluationTest' 2>&1;if($LASTEXITCODE){$log|Write-Host;throw 'M9 reliability instrumentation evaluation failed.'}}finally{Pop-Location}
$rows=@($log|ForEach-Object{if($_ -match 'M9_RESULT,([^,]+),(\d+),(\d+),(\d+),(PASS|FAIL)'){[pscustomobject]@{scenario=$Matches[1];attempts=[int]$Matches[2];successes=[int]$Matches[3];success_rate_pct=[math]::Round(100*[int]$Matches[3]/[int]$Matches[2],2);duplicates=[int]$Matches[4];result=$Matches[5]}}});if(!$rows.Count){throw 'No M9_RESULT records found; no result file written.'};$rows|Export-Csv -NoTypeInformation -Encoding utf8 $out;Write-Host "Wrote $out"
